60: /*
61:  * More room for the content column, on every docs page:
62:  * - page width 90rem -> 100rem: the one variable Nextra uses for the navbar,
63:  *   the main row and the footer, so the three stay aligned; on a 1920px screen
64:  *   the empty side margins drop from 240px to 160px;
65:  * - "Nesta página" (the TOC column) 16rem -> 13rem;
66:  * - article side padding 48px -> 32px from md up (x:md:px-12).
67:  * At 1440px the text column grows from 768px to 848px.
68:  * html:root, not :root: Nextra's <Head> injects ":root { --nextra-content-width:
69:  * 90rem }" in a <style> after this file, which wins at equal specificity.
70:  */
71: html:root {
72:   --nextra-content-width: 100rem;
73: }
